package org.diy.liferecorder;
import android.app.*;import android.content.*;import android.view.*;import android.widget.*;
/** Localized, adaptive alert/menu/form surfaces shared by every app dialog. */
final class LocalDialog extends AlertDialog.Builder {
 private final Context context;private CharSequence heading="";private boolean sheet;private DialogInterface.OnClickListener cancelAction;
 LocalDialog(Context c){super(c);context=c;}
 private CharSequence t(CharSequence s){return AppLanguage.text(context,s);}
 public LocalDialog rawMessage(CharSequence value){super.setMessage(value);return this;}
 public LocalDialog setTitle(CharSequence s){heading=t(s);return this;}public LocalDialog setMessage(CharSequence s){super.setMessage(t(s));return this;}
 public LocalDialog setView(View view){PebbleSurfaces.fields(view);if(view instanceof ScrollView)super.setView(view);else{ScrollView scroll=new ScrollView(context){protected void onMeasure(int w,int h){int max=(int)(getResources().getDisplayMetrics().heightPixels*.52);super.onMeasure(w,MeasureSpec.makeMeasureSpec(MeasureSpec.getMode(h)==MeasureSpec.UNSPECIFIED?max:Math.min(MeasureSpec.getSize(h),max),MeasureSpec.AT_MOST));}};scroll.setFillViewport(false);scroll.setClipToPadding(false);scroll.setPadding(0,0,0,PebbleSurfaces.dp(context,8));scroll.addView(view);super.setView(scroll);}return this;}
 public LocalDialog setItems(CharSequence[] values,DialogInterface.OnClickListener click){sheet=values.length>=4;CharSequence[] copy=new CharSequence[values.length];for(int i=0;i<values.length;i++)copy[i]=t(values[i]);ArrayAdapter<CharSequence> adapter=new ArrayAdapter<CharSequence>(context,android.R.layout.simple_list_item_1,copy){public View getView(int p,View old,ViewGroup parent){TextView text=(TextView)super.getView(p,old,parent);text.setTextSize(14);text.setTextColor(copy[p].toString().contains("删除")?0xffba1a1a:PebbleSurfaces.INK);text.setMinHeight(PebbleSurfaces.dp(context,50));text.setPadding(PebbleSurfaces.dp(context,16),PebbleSurfaces.dp(context,12),PebbleSurfaces.dp(context,16),PebbleSurfaces.dp(context,12));text.setBackground(PebbleSurfaces.states(context,0xfff7f3ee,0xffebe1d8,0xfff4f0eb,16));return text;}};super.setAdapter(adapter,click);return this;}
 public LocalDialog setMultiChoiceItems(CharSequence[] values,boolean[] checked,DialogInterface.OnMultiChoiceClickListener click){sheet=true;CharSequence[] translated=new CharSequence[values.length];for(int i=0;i<values.length;i++)translated[i]=t(values[i]);super.setMultiChoiceItems(translated,checked,click);return this;}
 public LocalDialog setPositiveButton(CharSequence s,DialogInterface.OnClickListener click){super.setPositiveButton(t(s),click);return this;}public LocalDialog setNegativeButton(CharSequence s,DialogInterface.OnClickListener click){cancelAction=click;super.setNegativeButton(t(s),click);return this;}public LocalDialog setNeutralButton(CharSequence s,DialogInterface.OnClickListener click){super.setNeutralButton(t(s),click);return this;}
 public AlertDialog create(){final AlertDialog[] result=new AlertDialog[1];LinearLayout header=new LinearLayout(context);header.setGravity(Gravity.CENTER_VERTICAL);header.setPadding(PebbleSurfaces.dp(context,22),PebbleSurfaces.dp(context,20),PebbleSurfaces.dp(context,16),PebbleSurfaces.dp(context,4));PebbleIcon icon=new PebbleIcon(context,heading.toString().contains("声")?"wave":heading.toString().contains("情境")?"heart":"spark",PebbleSurfaces.PRIMARY);icon.setPadding(PebbleSurfaces.dp(context,7),PebbleSurfaces.dp(context,7),PebbleSurfaces.dp(context,7),PebbleSurfaces.dp(context,7));icon.setBackground(PebbleSurfaces.surface(0xfffcf2e9,40,context));header.addView(icon,new LinearLayout.LayoutParams(PebbleSurfaces.dp(context,36),PebbleSurfaces.dp(context,36)));TextView title=new TextView(context);title.setText(heading.length()==0?t("请确认"):heading);title.setTextColor(PebbleSurfaces.INK);title.setTextSize(18);title.setTypeface(android.graphics.Typeface.create("sans-serif-medium",0));title.setPadding(PebbleSurfaces.dp(context,12),0,PebbleSurfaces.dp(context,8),0);header.addView(title,new LinearLayout.LayoutParams(0,-2,1));TextView close=new TextView(context);close.setText("×");close.setTextSize(24);close.setTextColor(PebbleSurfaces.MUTED);close.setGravity(Gravity.CENTER);close.setContentDescription(t("关闭弹窗"));close.setBackground(PebbleSurfaces.states(context,0xfff7f3ee,0xffebe1d8,0xfff4f0eb,24));header.addView(close,new LinearLayout.LayoutParams(PebbleSurfaces.dp(context,44),PebbleSurfaces.dp(context,44)));close.setOnClickListener(v->{if(result[0]!=null)result[0].cancel();});super.setCustomTitle(header);AlertDialog dialog=super.create();result[0]=dialog;dialog.setOnCancelListener(d->{if(cancelAction!=null)cancelAction.onClick(d,DialogInterface.BUTTON_NEGATIVE);});dialog.setOnShowListener(d->PebbleSurfaces.dialog(dialog,sheet));return dialog;}
}
